// Generated by scripts/build-production.js from src/server.js: the runtime without hot reloading. Do not edit.
// Server rendering of zubra elements, for framework integrations (the Astro renderer, …).
//
// A `.zb` module loads on a server: `define()` returns a stand-in that carries the element's
// `zubra` description and can't be constructed. The build plugin's server build of each component
// registers how to render it (through @zubra/compiler, with the component's sources embedded), and
// `renderToString(Element, …)` uses that. Without the plugin, render a file with
// `@zubra/compiler`'s `renderToString(path, …)` instead.

// One registry per process, even with several copies of the runtime.
const renderers = (globalThis[Symbol.for('zubra.renderers')] ??= new Map());

/** Register how to server-render `tag`: `(props, slots) => html`. Called by the plugin's output. */
export function registerRenderer(tag, render) {
  renderers.set(tag, render);
}

/** Whether `Element` is a zubra element that can be rendered here. */
export function canRender(Element) {
  return typeof Element?.zubra?.tag === 'string' && renderers.has(Element.zubra.tag);
}

/**
 * The element's server-rendered HTML, which it hydrates in the browser. `props` are its prop
 * values (JSON), `attributes` other attributes for the host (`class`, `id`, …), and `slots` the
 * supplied content by slot name (`default` for unnamed content), as HTML.
 */
export function renderToString(Element, { props = {}, attributes = {}, slots = {} } = {}) {
  const meta = Element?.zubra;
  if (!meta) throw new TypeError('zubra: renderToString() needs a compiled zubra element (the default export of a .zb module)');
  const render = renderers.get(meta.tag);
  if (!render) {
    throw new Error(`zubra: no server renderer for <${meta.tag}>; build it with the zubra plugin (in its server build), or use @zubra/compiler's renderToString(path)`);
  }
  for (const name of Object.keys(slots)) {
    if (name !== 'default' && !meta.slots.includes(name)) throw new Error(`zubra: <${meta.tag}> has no slot \`${name}\``);
  }
  const html = render(props, slots);
  const extra = Object.entries(attributes)
    .filter(([, value]) => value != null && value !== false)
    .map(([name, value]) => (value === true ? ` ${name}` : ` ${name}="${escapeAttribute(String(value))}"`))
    .join('');
  // Onto the host's start tag (the markup starts with it).
  return extra ? html.replace(/^(<[a-z][\w.-]*)/, `$1${extra}`) : html;
}

/**
 * An element's server-rendered content, for a host a framework renders bare: for a shadow-DOM
 * element its declarative shadow root (`<template shadowrootmode>…</template>`), for a light-DOM
 * element its rendered children (with their hydration markers); plus, for a form-associated
 * element with a `name`, a hidden input with the value it would submit (the element removes it
 * when it starts). The framework must leave the host's content alone while hydrating (React's
 * `dangerouslySetInnerHTML`, Vue's `innerHTML`). Empty when it can't be rendered here.
 */
export function serverContent(Element, { props = {}, name } = {}) {
  const meta = Element?.zubra;
  if (!meta || !canRender(Element)) return '';
  let html;
  try {
    html = renderers.get(meta.tag)(props, {});
  } catch {
    return ''; // left to the browser rather than break the page
  }
  let content = '';
  if (meta.shadow) {
    const start = html.search(/<template\s[^>]*shadowrootmode/i);
    if (start < 0) return '';
    let depth = 0;
    for (const match of html.slice(start).matchAll(/<template\b[^>]*>|<\/template>/gi)) {
      depth += match[0][1] === '/' ? -1 : 1;
      if (depth === 0) {
        content = html.slice(start, start + match.index + match[0].length);
        break;
      }
    }
  } else {
    // The host's children: from the end of its start tag to its end tag.
    const open = html.match(/^<[a-z][\w.-]*(?:\s[^>]*)?>/);
    const close = html.lastIndexOf(`</${meta.tag}>`);
    if (!open || close < open[0].length) return '';
    content = html.slice(open[0].length, close);
  }
  if (!content) return '';
  const models = Object.entries(meta.props).filter(([, spec]) => spec.model);
  if (!meta.form || !name || models.length !== 1) return content;
  const [[model, spec]] = models;
  const value = model in props ? props[model] : spec.default;
  if (value == null || value === false || value === '') return content;
  const text = value === true ? 'on' : typeof value === 'object' ? JSON.stringify(value) : String(value);
  return `${content}<input type="hidden" name="${escapeAttribute(String(name))}" value="${escapeAttribute(text)}" data-zb-fallback>`;
}

/** `serverContent` for a shadow-DOM element (the 2.11 name); empty for a light-DOM one. */
export function shadowContent(Element, options) {
  return Element?.zubra?.shadow ? serverContent(Element, options) : '';
}

const escapeAttribute = (value) => value.replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');
